vals <- c(1.2, 3.4, -0.5, 2.1, 0.8, 4.5, -1.2, 1.9, 3.0, 0.2, 2.7, -0.8, 1.5, 3.3, 0.6)
make_counter <- function(data) {
  threshold <- mean(data)
  count <- 0
  function(x) {
    if (x > threshold) count <<- count + 1
    return(count)
  }
}
counter <- make_counter(vals)
counts <- sapply(vals, counter)
answer <- counts[length(counts)] / length(vals)
